export function ellipsoid(scene,center,radius,color,axis=[0,1,0],rings=10,sides=18){const y=unit(axis),x=unit(cross(y,Math.abs(y[2])<.9?[0,0,1]:[1,0,0])),z=cross(x,y);const p=(i,j)=>{const a=Math.PI*i/rings,b=Math.PI*2*j/sides;return add(center,add(mul(x,Math.sin(a)*Math.cos(b)*radius[0]),add(mul(y,Math.cos(a)*radius[1]),mul(z,Math.sin(a)*Math.sin(b)*radius[2]))));};const n=(i,j)=>{const a=Math.PI*i/rings,b=Math.PI*2*j/sides;return unit(add(mul(x,Math.sin(a)*Math.cos(b)/radius[0]),add(mul(y,Math.cos(a)/radius[1]),mul(z,Math.sin(a)*Math.sin(b)/radius[2]))));};for(let i=0;i<rings;i++)for(let j=0;j<sides;j++){const a=p(i,j),b=p(i+1,j),c=p(i+1,j+1),d=p(i,j+1);if(i)scene.triangle(a,b,d,color,[n(i,j),n(i+1,j),n(i,j+1)]);if(i<rings-1)scene.triangle(b,c,d,color,[n(i+1,j),n(i+1,j+1),n(i,j+1)]);}}
