export function mannequinPose({x=0,z=0,yaw=0,bend=0,gesture=0,present=0,hip=0}={}){const transform=([a,b,c])=>[x+a*Math.cos(yaw)+c*Math.sin(yaw),b,z-a*Math.sin(yaw)+c*Math.cos(yaw)],local={pelvis:[0,1.05,0],chest:[0,1.76+bend*-.25,bend*.55],neck:[0,2.08-bend*.35,bend*.75],head:[0,2.24-bend*.43,bend*.83],leftShoulder:[-.3,1.94-bend*.3,bend*.7],rightShoulder:[.3,1.94-bend*.3,bend*.7],leftElbow:[-.43-hip*.15,1.48-bend*.2,.12+gesture*.08],rightElbow:[.43,1.43-bend*.2,.1+present*.2],leftWrist:[-.31-gesture*.12,1.12+gesture*.36+hip*.15,.16+gesture*.5],rightWrist:[.34,1.08+present*.46,.2+present*.65],leftKnee:[-.17,.54,-bend*.04],rightKnee:[.17,.54,-bend*.04],leftAnkle:[-.17,.1,0],rightAnkle:[.17,.1,0]};return Object.fromEntries(Object.entries(local).map(([k,v])=>[k,transform(v)]));}
